  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 11, 'g11_st3', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Nhận biết một số ngành nghề sử dụng kiến thức sinh học cơ thể.', '{"textWithBlanks":"Kiến thức sinh lí cây trồng được ứng dụng nhiều trong [blank].","bankWords":["trồng trọt","thiên văn học","cơ khí ô tô"],"hint":"Từ cần chọn gồm 2 tiếng và bắt đầu bằng chữ “t”."}'::jsonb, '{"value":"trồng trọt","explanation":"Từ đúng là “trồng trọt”."}'::jsonb, '[{"source":"SGK Sinh học 11 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 29. Một số ngành nghề liên quan đến sinh học cơ thể"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
$station_release$;
commit;
